init:
(function () {
  // BG1.6 check, with BG1.4's guard. X8.9: loke's /api/settings reads (and a save writes) the user's real login
  // keychain, which a throwaway HOME does not isolate, so no /api/settings request from these
  // pages reaches any server: it is recorded here, with the URL the page chose, and answered.
  window.__bg14Settings = [];
  var real = window.fetch;
  window.fetch = function (u, o) {
    var s = String(u && u.url ? u.url : u);
    if (/\/api\/settings(\?|$)/.test(s)) {
      window.__bg14Settings.push({ url: s, method: (o && o.method) || 'GET' });
      return Promise.resolve(new Response(JSON.stringify({ ok: true, anthropic: 'not_configured', openai: 'not_configured', answered_by: 'the BG1.4 check, not loke' }), { status: 200, headers: { 'Content-Type': 'application/json' } }));
    }
    return real.apply(this, arguments);
  };
  // lokehealth has no base layout, so nothing sets window.LOKE_URL there; set it to '' as
  // base.tkt does when moke answers for loke.
  if (location.pathname === '/lokehealth') window.LOKE_URL = '';
})();
